export function marketContext(year, priorStockReturn) {
  if (year < 2019) return legacyContext(year, priorStockReturn);
  const i = year - 2019;
  const [pd, rate, pt, px] = policies[i];
  const [jd, unemployment, jt, jx] = jobs[i];
  const [id, tag, it, ix, iu] = industries[i];
  const pu = `https://www.federalreserve.gov/newsevents/pressreleases/monetary${pd.replaceAll('-', '')}a.htm`;
  const ju = `https://www.bls.gov/news.release/archives/empsit_${jd.slice(5,7)}${jd.slice(8,10)}${jd.slice(0,4)}.htm`;
  const item = (tag,title,text,sourceUrl,asOf) => ({tag,title,text,sourceUrl,asOf,publishedAt:asOf});
  return {
    briefing: [item('经济 · 政策',pt,px,pu,pd),item(tag,it,ix,iu,id),item('社会 · 就业',jt,jx,ju,jd)],
    marketSignals: [
      {label:'政策利率',value:rate,context:'年初已公开的联邦基金目标区间；非游戏现金利率',sourceUrl:pu,asOf:pd,publishedAt:pd},
      {label:`${year-1} 年 11 月失业率`,value:`${unemployment.toFixed(1)}%`,context:`采用 ${jd} 已发布口径，非事后修订值`,sourceUrl:ju,asOf:jd,publishedAt:jd},
      {label:`${year-1} 年宽基回报`,value:`${priorStockReturn>=0?'+':''}${priorStockReturn.toFixed(2)}%`,context:'标普 500 含分红；已结束年份的历史整理值',sourceUrl:'https://pages.stern.nyu.edu/adamodar/New_Home_Page/datafile/histretSP.html',asOf:`${year-1}-12-31`,observationEnd:`${year-1}-12-31`,retrospective:true,sourceVintage:'2026-01-05'}
    ]
  };
}
